		F_set follow = findFollow(rules[i].left, rules);
		for (unsigned int j = 0; j < rules[i].right.size(); j++) {
			//单元格里存放的是“左部::=本候选式”这一条产生式
			rule cell;
			cell.left = rules[i].left;
			cell.right.push_back(rules[i].right[j]);
			F_set first = findFirst(rules[i].right[j], rules);
			set<char> cols;
			for (set<char>::iterator it = first.right.begin(); it != first.right.end(); it++) {
				if (*it != '@') {
					cols.insert(*it);//终结符a属于First集，则[左部,a]处填该候选式
					continue;
				}
				//候选式能推出空串，则Follow集中的每一个符号所在列都填该候选式
				for (set<char>::iterator ft = follow.right.begin(); ft != follow.right.end(); ft++) {
					cols.insert(*ft);
				}
			}
			for (set<char>::iterator it = cols.begin(); it != cols.end(); it++) {
				int c = index_of(table.col, *it);
				if (c < 0) {
					continue;//该符号不是文法的终结符，分析表中没有对应的列
				}
				if (!table.rules[r * table.col.size() + c].right.empty()) {
					continue;//单元格已被占用（文法不满足LL(1)条件），保留先填入的产生式
				}
				table.rules[r * table.col.size() + c] = cell;
			}
		}
	}
	return table;
}
```

Clause map:
* *"FIRST sets for direct terminals"* — `cols.insert(*it)` for every non-`@` member of `FIRST(candidate)`.
* *"FOLLOW sets when `@` appears in a production FIRST set"* — the `*it == '@'` branch unions the whole `FOLLOW(left)`; this is the **per-candidate** FIRST (not FIRST of the non-terminal), which is what makes `[M,a]=M::=Ab` and `[M,b]=M::=@` land in different cells.
* Each cell stores a *single-candidate* rule (`cell.right` has exactly one string), so `operator<<(rule)` renders `M::=Ab`, never `M::=Ab|@` — required by `test_parser_units.cpp:157-161`.
* `cols` is a `set<char>`, so a symbol appearing in both FIRST and FOLLOW is written once.
* The occupancy check keeps the first-written production on a conflict instead of silently overwriting; the grammar is then not LL(1) and the lab's grammars never hit it.

