string load_file(string file_name) {
	cout << "正在读取文法文件：" << file_name << endl;
	ifstream in(file_name.c_str());
	if (!in) {
		cout << "文法文件打开失败，请检查文件是否存在：" << file_name << endl;
		return "";
	}
	//把文件内容整体流入字符串缓冲区
	stringstream buffer;
	buffer << in.rdbuf();
	in.close();
	string text = buffer.str();
	cout << "文法文件读取成功，文法内容如下：" << endl;
	cout << text << endl << endl;
	return text;
}
ostream& operator << (ostream& out, rule rule) {
	//规则以“左部::=右部1|右部2|...”的形式输出
	out << rule.left << "::=";
	for (unsigned int i = 0; i < rule.right.size(); i++) {
		if (i > 0) {
			out << "|";
		}
		out << rule.right[i];
	}
	return out;
}
void split_into_rules(const string text, vector<rule> &rules, set<char> &non_terminal, set<char> &terminal, set<string> &right_parts) {
	//各条文法规则之间以空白分隔，每条规则形如“左部::=右部1|右部2|...”
	stringstream ss(text);
	string item;
	while (ss >> item) {
		string::size_type pos = item.find("::=");
		if (pos == string::npos || pos == 0) {
			continue;//不是一条合法的产生式，直接忽略
		}
		char left = item[0];
		string rights = item.substr(pos + 3);

		//右部按“|”切分成若干个候选式
		vector<string> parts;
		string part = "";
		for (unsigned int i = 0; i < rights.length(); i++) {
			if (rights[i] == '|') {
				parts.push_back(part);
				part = "";
			}
			else {
				part += rights[i];
			}
		}
		parts.push_back(part);

		//同一个非终结符的产生式可能分开书写，合并到同一条规则中
		int at = -1;
		for (unsigned int i = 0; i < rules.size(); i++) {
			if (rules[i].left == left) {
				at = (int)i;
				break;
			}
		}
		if (at < 0) {
			rule new_rule;
			new_rule.left = left;
			rules.push_back(new_rule);
			at = (int)rules.size() - 1;
		}
		for (unsigned int i = 0; i < parts.size(); i++) {
			if (!parts[i].empty()) {
				rules[at].right.push_back(parts[i]);
			}
		}
		//出现在规则左部的一定是非终结符
		non_terminal.insert(left);
	}

	//所有规则左部都收集完毕之后，再回头区分右部中的终结符和非终结符
	for (unsigned int i = 0; i < rules.size(); i++) {
		for (unsigned int j = 0; j < rules[i].right.size(); j++) {
			const string& part = rules[i].right[j];
			right_parts.insert(part);
			for (unsigned int k = 0; k < part.length(); k++) {
				char c = part[k];
				if (c == '@') {
					continue;//“@”代表空串ε，既不是终结符也不是非终结符
				}
				if (non_terminal.count(c) > 0) {
					continue;
				}
				if (isupper((unsigned char)c)) {
					non_terminal.insert(c);//大写字母一律看作非终结符
				}
				else {
					terminal.insert(c);
				}
			}
		}
	}
}
