void print_state(stack<char> analysis_s, stack<char> input_s, rule& rule_temp) {
	string analysis = "";
	while (!analysis_s.empty()) {
		analysis = string(1, analysis_s.top()) + analysis;
		analysis_s.pop();
	}
	string input = "";
	while (!input_s.empty()) {
		input += input_s.top();
		input_s.pop();
	}
	ostringstream action;
	if (!rule_temp.right.empty()) {
		action << rule_temp;
	}
	else if (rule_temp.left != 0) {
		action << "“" << rule_temp.left << "”匹配";
	}
