	for (int i = (int)input.length() - 1; i >= 0; i--) {
		input_s.push(input[i]);
	}

	bool success = true;
	if (table.row.empty() || table.col.empty()) {
		cout << "没有可用的文法规则，无法进行语法分析" << endl;
		success = false;
	}
	for (unsigned int i = 0; success && i < input.length(); i++) {
		if (find_col(table, input[i]) < 0) {
			cout << "输入串中的“" << input[i] << "”不是该文法的终结符" << endl;
			success = false;
		}
	}

	cout << endl << setw(20) << "分析栈" << setw(20) << "剩余输入串" << setw(20) << "所用产生式" << endl;
	const int MAX_STEP = 500 + 100 * (int)input.length();
	int step = 0;
	while (success) {
		step++;
		if (step > MAX_STEP) {
			cout << "分析步数超过上限" << MAX_STEP << "，分析终止" << endl;
			success = false;
			break;
		}
		if (analysis_s.empty() || input_s.empty()) {
			success = false;
			break;
		}
		char top = analysis_s.top();
		char cur = input_s.top();
		rule rule_temp;
		rule_temp.left = 0;
		if (top == '#') {
			print_state(analysis_s, input_s, rule_temp);
			if (cur != '#') {
				cout << "分析栈已经归约完毕，输入串却还剩下“" << cur << "”，分析失败" << endl;
				success = false;
			}
			break;
		}
		int r = find_row(table, top);
		if (r < 0) {
			if (top != cur) {
				print_state(analysis_s, input_s, rule_temp);
				cout << "栈顶终结符“" << top << "”与输入符号“" << cur << "”不匹配，分析失败" << endl;
				success = false;
				break;
			}
			rule_temp.left = top;
			print_state(analysis_s, input_s, rule_temp);
			analysis_s.pop();
			input_s.pop();
			continue;
		}
		int c = find_col(table, cur);
		unsigned int at = 0;
		if (c >= 0) {
			at = (unsigned int)r * table.col.size() + (unsigned int)c;
		}
		if (c < 0 || at >= table.rules.size() || table.rules[at].right.empty()) {
			print_state(analysis_s, input_s, rule_temp);
			cout << "分析表中[" << top << "," << cur << "]处没有产生式，分析失败" << endl;
			success = false;
			break;
		}
		rule_temp = table.rules[at];
		print_state(analysis_s, input_s, rule_temp);
		analysis_s.pop();
		const string& right_part = rule_temp.right[0];
		for (int k = (int)right_part.length() - 1; k >= 0; k--) {
			if (right_part[k] == '@') {
				continue;
			}
			analysis_s.push(right_part[k]);
		}
	}

	cout << endl << "字符串" << input;
	if (!success) {
		cout << "不";
	}
	cout << "是该文法的句子" << endl;
}
