static bool is_non_terminal(const char c, const vector<rule>& rules) {
	for (unsigned int i = 0; i < rules.size(); i++) {
		if (rules[i].left == c) {
			return true;
		}
	}
	return false;
}
static set<char> firstOf(const string ss, const vector<rule>& rules, set<char>& visiting) {
	set<char> result;
	bool all_epsilon = true;
	for (unsigned int i = 0; i < ss.length(); i++) {
		char c = ss[i];
		if (c == '@') {
			continue;
		}
		if (!is_non_terminal(c, rules)) {
			result.insert(c);
			all_epsilon = false;
			break;
		}
		if (visiting.count(c) > 0) {
			all_epsilon = false;
			break;
		}
		visiting.insert(c);
		bool has_epsilon = false;
		for (unsigned int j = 0; j < rules.size(); j++) {
			if (rules[j].left != c) {
				continue;
			}
			for (unsigned int k = 0; k < rules[j].right.size(); k++) {
				set<char> sub = firstOf(rules[j].right[k], rules, visiting);
				for (set<char>::iterator it = sub.begin(); it != sub.end(); it++) {
					if (*it == '@') {
						has_epsilon = true;
					}
					else {
						result.insert(*it);
					}
				}
			}
		}
		visiting.erase(c);
		if (!has_epsilon) {
			all_epsilon = false;
			break;
		}
	}
	if (all_epsilon) {
		result.insert('@');
	}
	return result;
}
F_set findFirst(const string ss, vector<rule> rules) {
	F_set f_set;
	f_set.is_first = true;
	f_set.left = ss;
	set<char> visiting;
	f_set.right = firstOf(ss, rules, visiting);
	return f_set;
}
