}
static int index_of(const vector<char>& head, const char c) {
	for (unsigned int i = 0; i < head.size(); i++) {
		if (head[i] == c) {
			return (int)i;
		}
	}
	return -1;
}
LL_1_table LL_1(set<char>& terminal, set<char>& non_terminal, vector<rule> rules) {
	LL_1_table table;
	for (unsigned int i = 0; i < rules.size(); i++) {
		if (index_of(table.row, rules[i].left) < 0) {
			table.row.push_back(rules[i].left);
		}
	}
	for (set<char>::iterator it = non_terminal.begin(); it != non_terminal.end(); it++) {
		if (index_of(table.row, *it) < 0) {
			table.row.push_back(*it);
		}
	}
	for (set<char>::iterator it = terminal.begin(); it != terminal.end(); it++) {
		if (*it == '#' || *it == '@') {
			continue;
		}
		table.col.push_back(*it);
	}
	table.col.push_back('#');
	rule empty_rule;
	empty_rule.left = ' ';
	table.rules.assign(table.row.size() * table.col.size(), empty_rule);
	for (unsigned int i = 0; i < rules.size(); i++) {
		int r = index_of(table.row, rules[i].left);
		if (r < 0) {
			continue;
		}
		F_set follow = findFollow(rules[i].left, rules);
		for (unsigned int j = 0; j < rules[i].right.size(); j++) {
			rule cell;
			cell.left = rules[i].left;
			cell.right.push_back(rules[i].right[j]);
			F_set first = findFirst(rules[i].right[j], rules);
			set<char> cols;
			for (set<char>::iterator it = first.right.begin(); it != first.right.end(); it++) {
				if (*it != '@') {
					cols.insert(*it);
					continue;
				}
				for (set<char>::iterator ft = follow.right.begin(); ft != follow.right.end(); ft++) {
					cols.insert(*ft);
				}
			}
			for (set<char>::iterator it = cols.begin(); it != cols.end(); it++) {
				int c = index_of(table.col, *it);
				if (c < 0) {
					continue;
				}
				if (!table.rules[r * table.col.size() + c].right.empty()) {
					continue;
				}
				table.rules[r * table.col.size() + c] = cell;
			}
		}
	}
	return table;
}
