static string cell(LL_1_table& t, char nt, char term) {
	int i = -1, j = -1;
	for (unsigned int r = 0; r < t.row.size(); r++) {
		if (t.row[r] == nt) {
			i = (int)r;
		}
	}
	for (unsigned int c = 0; c < t.col.size(); c++) {
		if (t.col[c] == term) {
			j = (int)c;
		}
	}
	if (i < 0 || j < 0) {
		return "?";
	}
	rule r = t.rules[i * t.col.size() + j];
	if (r.right.empty()) {
		return "";
	}
	ostringstream os;
