static void test_table() {
	grammar g(G3);
	LL_1_table t = LL_1(g.terminal, g.non_terminal, g.rules);
	//行表头按规则出现顺序排列，第一行就是文法开始符号
	expect_eq(string(t.row.begin(), t.row.end()), "EHMA", "G3 table rows");
	expect_eq(string(t.col.begin(), t.col.end()), "abde#", "G3 table cols");
	expect_eq(cell(t, 'E', 'a'), "E::=aH", "G3 [E,a]");
	expect_eq(cell(t, 'E', 'b'), "", "G3 [E,b] empty");
	expect_eq(cell(t, 'H', 'a'), "H::=aMd", "G3 [H,a]");
	expect_eq(cell(t, 'H', 'd'), "H::=d", "G3 [H,d]");
	expect_eq(cell(t, 'M', 'a'), "M::=Ab", "G3 [M,a]");
	expect_eq(cell(t, 'M', 'e'), "M::=Ab", "G3 [M,e]");
	expect_eq(cell(t, 'M', 'b'), "M::=@", "G3 [M,b]");
	expect_eq(cell(t, 'M', 'd'), "M::=@", "G3 [M,d]");
	expect_eq(cell(t, 'M', '#'), "M::=@", "G3 [M,#]");
	expect_eq(cell(t, 'A', 'a'), "A::=aM", "G3 [A,a]");
	expect_eq(cell(t, 'A', 'e'), "A::=e", "G3 [A,e]");
	expect_eq(cell(t, 'A', 'b'), "", "G3 [A,b] empty");

	grammar g1(G1);
	LL_1_table t1 = LL_1(g1.terminal, g1.non_terminal, g1.rules);
	expect_eq(string(t1.row.begin(), t1.row.end()), "ETG", "G1 table rows");
	expect_eq(cell(t1, 'E', 'a'), "E::=a", "G1 [E,a]");
	expect_eq(cell(t1, 'E', 'b'), "E::=b", "G1 [E,b]");
	expect_eq(cell(t1, 'E', '('), "E::=(T)", "G1 [E,(]");
	expect_eq(cell(t1, 'T', 'a'), "T::=EG", "G1 [T,a]");
	expect_eq(cell(t1, 'T', '('), "T::=EG", "G1 [T,(]");
	expect_eq(cell(t1, 'G', ','), "G::=,EG", "G1 [G,,]");
	expect_eq(cell(t1, 'G', ')'), "G::=@", "G1 [G,)]");
	expect_eq(cell(t1, 'G', '#'), "G::=@", "G1 [G,#]");
	expect_eq(cell(t1, 'G', 'a'), "", "G1 [G,a] empty");
}

